<?php require __DIR__.'/../includes/bootstrap.php'; if(logged_in()){header('Location: index.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check(); $q=$pdo->prepare('SELECT id,name,email,password_hash FROM admins WHERE email=?');$q->execute([trim($_POST['email']??'')]);$a=$q->fetch();if($a && password_verify($_POST['password']??'', $a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['name'];header('Location: index.php');exit;} $error='Incorrect email or password.';} ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin login</title><link rel="stylesheet" href="style.css"></head><body><div class="wrap" style="max-width:440px"><div class="panel"><h1>Administrator login</h1><p class="muted">Bright Futures Foundation</p><?php if($error):?><p style="color:#a00"><?=e($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Email address</label><input type="email" name="email" required autocomplete="username"><label>Password</label><input type="password" name="password" required autocomplete="current-password"><button class="btn">Log in</button></form><p><a href="../index.html">Return to website</a></p></div></div></body></html>